import java.util.*;

class DistanceLimitedPathsExist {
  // union-find that remembers when each link was made (the edge weight); no path compression,
  // so for any limit the components are those formed by edges lighter than it
  private final int[] parent, size, linkedAt;

  public DistanceLimitedPathsExist(int n, int[][] edgeList) {
    parent = new int[n];
    size = new int[n];
    linkedAt = new int[n];
    for (int i = 0; i < n; i++) {
      parent[i] = i;
      size[i] = 1;
      linkedAt[i] = Integer.MAX_VALUE;
    }
    int[][] edges = edgeList.clone();
    Arrays.sort(edges, (a, b) -> Integer.compare(a[2], b[2]));
    for (int[] e : edges) {
      int a = find(e[0], Integer.MAX_VALUE), b = find(e[1], Integer.MAX_VALUE);
      if (a == b) continue;
      if (size[a] < size[b]) {
        int t = a;
        a = b;
        b = t;
      }
      parent[b] = a; // union by size keeps the trees shallow
      size[a] += size[b];
      linkedAt[b] = e[2];
    }
  }

  public boolean query(int p, int q, int limit) {
    return find(p, limit) == find(q, limit);
  }

  private int find(int x, int limit) {
    while (parent[x] != x && linkedAt[x] < limit) x = parent[x];
    return x;
  }
}
